/// <summary>
///     The <c>AVASysDocuBrandDetailsFrm_Extension</c> class is the extension for <c>SysDocuBrandDetails</c>
/// </summary>
[ExtensionOf(FormStr(SysDocuBrandDetails))]
final class AVASysDocuBrandDetailsFrm_Extension
{
}

Method.Source:
/// <summary>
/// Display image in form image control
/// </summary>
/// <param name = "imageData">The container of image data.</param>
/// <param name = "image">The form image control</param>
public void avaShowImage(Container imageData, FormWindowControl image)
{
    Image   logoImage;

    if (imageData)
    {
        logoImage = new Image();
        logoImage.setData(imageData);
        image.image(logoImage);
    }
    else
    {
        image.image(null);
    }
}

/// <summary>
/// Show images in form controls if images have been set up.
/// </summary>
public void avaShowLogo()
{
    try
    {
        if (SysDocuBrandDetails.Image1Name)
        {
            this.avaShowImage(SysDocuBrandImages::find(SysDocuBrandDetails.Image1Name).Image, AVAImage1);
        }
        else
        {
            this.avaShowImage(conNull(), AVAImage1);
        }

        if (SysDocuBrandDetails.Image2Name)
        {
            this.avaShowImage(SysDocuBrandImages::find(SysDocuBrandDetails.Image2Name).Image, AVAImage2);
        }
        else
        {
            this.avaShowImage(conNull(), AVAImage2);
        }

        if (SysDocuBrandDetails.Image3Name)
        {
            this.avaShowImage(SysDocuBrandImages::find(SysDocuBrandDetails.Image3Name).Image, AVAImage3);
        }
        else
        {
            this.avaShowImage(conNull(), AVAImage3);
        }

        if (SysDocuBrandDetails.AVAImage1NameInternational)
        {
            this.avaShowImage(SysDocuBrandImages::find(SysDocuBrandDetails.AVAImage1NameInternational).Image, AVAImage1International);
        }
        else
        {
            this.avaShowImage(conNull(), AVAImage1International);
        }

        if (SysDocuBrandDetails.AVAImage2NameInternational)
        {
            this.avaShowImage(SysDocuBrandImages::find(SysDocuBrandDetails.AVAImage2NameInternational).Image, AVAImage2International);
        }
        else
        {
            this.avaShowImage(conNull(), AVAImage2International);
        }

        if (SysDocuBrandDetails.AVAImage3NameInternational)
        {
            this.avaShowImage(SysDocuBrandImages::find(SysDocuBrandDetails.AVAImage3NameInternational).Image, AVAImage3International);
        }
        else
        {
            this.avaShowImage(conNull(), AVAImage3International);
        }
    }
    catch (Exception::Warning)
    {
        throw error("@SYS60147");
    }
}
